def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    giraffes = image_patch.find("giraffe")
    if not giraffes: return image_patch

    # Find the first giraffe in front of another giraffe
    for i, giraffe in enumerate(giraffes):
        if i < len(giraffes) - 1:
            if is_in_front_of(giraffe, giraffes[i + 1]):
                # Check if the second giraffe is in motion
                if giraffes[i + 1].verify_property("giraffe", "in motion"):
                    return giraffe
    return giraffes[0]

